export const headerStyles = /* css */ `
/* Carbon's <body> styles, so the page's don't leak in */
:host {
  display: contents;
  color: var(--cds-text-primary, #161616);
  font-family: var(--mc-font-family-default, Arial, Helvetica, sans-serif);
  font-size: 1rem;
  font-weight: var(--mc-font-weight-regular, 400);
  letter-spacing: normal;
  line-height: 1;
  text-align: initial;
  -moz-osx-font-smoothing: grayscale;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

/* Carbon UI Shell header restyled */
.mc-header.cds--header {
  block-size: var(--mc-header-height);
  border-block-end: var(--mc-header-border-width) solid var(--mc-header-accent);
  background: var(--mc-header-background);
}

/* ---------- Logo ---------- */
/* A div, so Carbon's a.cds--header__name layout is restated here */
.mc-header .cds--header__name {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  block-size: 100%;
  padding-inline: 1.5rem 2rem;
}

.mc-header__logo {
  display: block;
  block-size: var(--mc-header-logo-height);
  inline-size: auto;
}

/* ---------- Navigation icons ---------- */
.mc-header__external-icon {
  display: inline-block;
  margin-inline-start: 0.375rem;
  vertical-align: -0.0625rem;
  inline-size: 0.75rem;
  block-size: 0.75rem;
  fill: currentColor;
}

.mc-header__nav-icon {
  display: inline-flex;
  flex-shrink: 0;
  margin-inline-end: 0.75rem;
  fill: currentColor;
}

.mc-header__nav-icon svg {
  inline-size: 1.125rem;
  block-size: 1.125rem;
}

/* ---------- User ---------- */
.mc-header__user {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding-inline: 1rem 0.5rem;
  color: inherit;
  text-decoration: none;
}

.mc-header__avatar {
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  flex-shrink: 0;
  inline-size: 2.5rem;
  block-size: 2.5rem;
  color: var(--mc-header-icon);
}

.mc-header__avatar svg {
  inline-size: 2rem;
  block-size: 2rem;
  fill: currentColor;
}

.mc-header__avatar img {
  inline-size: 100%;
  block-size: 100%;
  border-radius: 50%;
  object-fit: cover;
}

.mc-header__user-name {
  color: var(--mc-header-icon);
  font-size: 0.8125rem;
  line-height: 1.3;
}

/* ---------- Small screens: top bar with a menu button + dropdown panel ---------- */
.mc-header .mc-header__menu-toggle {
  margin-inline-start: auto;
  block-size: 100%;
  inline-size: 4rem;
  border-radius: 0;
}

.mc-header .mc-header__menu-toggle svg {
  inline-size: 1.5rem;
  block-size: 1.5rem;
  fill: var(--mc-header-icon);
}

.mc-header__panel {
  position: absolute;
  inset-block-start: calc(100% + var(--mc-header-border-width));
  inset-inline: 0;
  overflow-y: auto;
  max-block-size: calc(100dvh - var(--mc-header-height));
  border-block-end: var(--mc-header-border-width) solid var(--mc-header-accent);
  background: var(--mc-header-background);
  box-shadow: 0 4px 8px 0 rgb(0 0 0 / 0.2);
}

.mc-header__panel-list,
.mc-header__panel-sublist {
  margin: 0;
  padding: 0;
  list-style: none;
}

.mc-header__panel-link {
  display: flex;
  align-items: center;
  inline-size: 100%;
  padding: 1rem 1.5rem;
  border: 0;
  border-inline-start: 3px solid transparent;
  background: none;
  color: var(--cds-text-primary, #161616);
  cursor: pointer;
  font: inherit;
  font-size: 0.875rem;
  font-weight: 500;
  letter-spacing: 0.02em;
  text-align: start;
  text-decoration: none;
  text-transform: uppercase;
}

.mc-header__panel-link:hover {
  background: var(--cds-background-hover, rgb(141 141 141 / 0.12));
}

.mc-header__panel-link:focus-visible,
.mc-header__panel-action:focus-visible {
  outline: 2px solid var(--cds-focus, var(--mc-color-brand-400));
  outline-offset: -2px;
}

.mc-header__panel-link[aria-current='page'],
.mc-header__panel-group[data-current] {
  border-inline-start-color: var(--mc-header-nav-indicator);
  color: var(--mc-header-nav-current);
  font-weight: max(500, var(--mc-header-nav-current-weight));
}

/* Background on the page itself, not on its open group */
.mc-header__panel-link[aria-current='page'] {
  background: var(--mc-header-nav-current-background);
}

.mc-header__panel-chevron {
  margin-inline-start: auto;
  inline-size: 1rem;
  block-size: 1rem;
  fill: currentColor;
  transition: transform 110ms;
}

.mc-header__panel-group[aria-expanded='true'] .mc-header__panel-chevron {
  transform: rotate(180deg);
}

.mc-header__panel-sublist .mc-header__panel-link {
  padding-inline-start: 2.5rem;
  font-weight: 400;
  letter-spacing: 0;
  text-transform: none;
}

.mc-header__panel-sublist .mc-header__panel-link[aria-current='page'] {
  font-weight: max(400, var(--mc-header-nav-current-weight));
}

.mc-header__panel-footer {
  display: flex;
  flex-direction: column;
  padding-block: 0.5rem;
  border-block-start: 2px solid var(--mc-header-accent);
}

/* User + logout, actions and language, each separated by a line */
.mc-header__panel-group-section {
  display: flex;
  flex-direction: column;
}

.mc-header__panel-group-section + .mc-header__panel-group-section {
  margin-block-start: 0.5rem;
  padding-block-start: 0.5rem;
  border-block-start: 1px solid var(--cds-border-subtle, #e0e0e0);
}

/* Same icon column and text start as the actions below */
.mc-header__panel-footer .mc-header__user {
  gap: 1rem;
  padding: 0.75rem 1.5rem;
}

.mc-header__panel-footer .mc-header__avatar,
.mc-header__panel-footer .mc-header__avatar svg {
  inline-size: 1.5rem;
  block-size: 1.5rem;
}

.mc-header__panel-footer .mc-header__user-name {
  font-size: 0.875rem;
}

.mc-header__panel-action {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 0.75rem 1.5rem;
  border: 0;
  background: none;
  color: var(--mc-header-icon);
  cursor: pointer;
  fill: currentColor;
  font: inherit;
  font-size: 0.875rem;
  text-align: start;
}

.mc-header__panel-action:hover,
.mc-header__panel-action[aria-pressed='true'] {
  background: var(--mc-color-brand-50);
}

.mc-header__panel-action svg {
  flex-shrink: 0;
  inline-size: 1.5rem;
  block-size: 1.5rem;
  fill: currentColor;
}

.mc-header__panel-language {
  inline-size: 1.5rem;
  font-size: 1rem;
  font-weight: 500;
  text-align: center;
}

/* ---------- Wide screens: fixed left sidebar ---------- */
.mc-sidebar {
  position: fixed;
  inset-block: 0;
  inset-inline-start: 0;
  z-index: 8000;
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  inline-size: var(--mc-header-sidebar-width);
  border-inline-end: var(--mc-header-border-width) solid var(--mc-header-accent);
  background: var(--mc-header-background);
}

.mc-sidebar__name {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  min-block-size: 4.5rem;
  padding-inline: 1.5rem;
  border-block-end: 1px solid var(--cds-border-subtle, #e0e0e0);
}

.mc-sidebar .mc-header__panel-nav {
  flex: 1;
  padding-block: 0.5rem;
}

.mc-sidebar .mc-header__panel-footer {
  position: sticky;
  inset-block-end: 0;
  background: var(--mc-header-background);
}
`;

/* Added to the page: shadow CSS can't reach inside slotted nodes */
export const slottedStyles = /* css */ `
mc-header .mc-header__logo {
  display: block;
  block-size: var(--mc-header-logo-height);
  inline-size: auto;
}

mc-header > svg[slot^='nav-icon-'],
mc-header > [slot^='nav-icon-'] svg {
  inline-size: 1.125rem;
  block-size: 1.125rem;
}

/* Wide screens: no top bar to clear, content moves right instead */
@media (min-width: 66rem) {
  :root:has(mc-header) {
    --mc-header-height: 0px;
  }

  body:has(mc-header) {
    padding-inline-start: var(--mc-header-sidebar-width);
  }
}

/* Action icons in the sidebar and the mobile menu */
mc-header > svg[slot^='action-icon-'],
mc-header > [slot^='action-icon-'] svg {
  flex-shrink: 0;
  inline-size: 1.5rem;
  block-size: 1.5rem;
  fill: inherit;
}
`;
