import cesnetLogoUrl from '../../assets/cesnet-logo.svg';
import einfraLogoUrl from '../../assets/einfra-logo.svg';
import metacentrumLogoUrl from '../../assets/metacentrum-logo.svg';
import { footerStyles } from './footer.styles';

export interface FooterLogo {
  src: string;
  alt: string;
  href?: string;
}

export const DEFAULT_FOOTER_LOGOS: FooterLogo[] = [
  { src: metacentrumLogoUrl, alt: 'MetaCentrum', href: 'https://metacentrum.cz' },
  { src: cesnetLogoUrl, alt: 'CESNET', href: 'https://www.cesnet.cz' },
  { src: einfraLogoUrl, alt: 'e-INFRA CZ', href: 'https://www.e-infra.cz' },
];

const TEMPLATE = `
<footer part="footer">
  <div class="inner" part="inner">
    <div class="info" part="info"><slot name="info"></slot></div>
    <ul class="logos" part="logos"></ul>
    <p class="copyright" part="copyright"><slot name="copyright"></slot></p>
  </div>
</footer>
`;

// Lazy, so importing on the server doesn't throw
let sheet: CSSStyleSheet | undefined;
function getSheet() {
  if (!sheet) {
    sheet = new CSSStyleSheet();
    sheet.replaceSync(footerStyles);
  }
  return sheet;
}

// SSR
const Base = (typeof HTMLElement === 'undefined' ? class {} : HTMLElement) as typeof HTMLElement;

/** Attributes, slots and properties: see README. */
export class McFooter extends Base {
  static observedAttributes = ['info', 'copyright'];

  #logos: FooterLogo[] = DEFAULT_FOOTER_LOGOS;

  constructor() {
    super();
    const root = this.attachShadow({ mode: 'open' });
    root.adoptedStyleSheets = [getSheet()];
    root.innerHTML = TEMPLATE;
    root.addEventListener('slotchange', () => this.#updateText());
    this.#renderLogos();
    this.#updateText();
  }

  connectedCallback() {
    // Set before the element was defined
    if (Object.prototype.hasOwnProperty.call(this, 'logos')) {
      const value = (this as { logos?: FooterLogo[] }).logos;
      delete (this as { logos?: FooterLogo[] }).logos;
      this.logos = value;
    }
  }

  get logos(): FooterLogo[] {
    return this.#logos;
  }

  /** `undefined` restores the defaults. */
  set logos(value: FooterLogo[] | undefined) {
    this.#logos = value ?? DEFAULT_FOOTER_LOGOS;
    this.#renderLogos();
  }

  attributeChangedCallback() {
    this.#updateText();
  }

  #updateText() {
    for (const name of ['info', 'copyright']) {
      const slot = this.shadowRoot!.querySelector<HTMLSlotElement>(`slot[name="${name}"]`)!;
      const text = this.getAttribute(name) ?? '';
      // Avoids a slotchange loop
      if (slot.textContent !== text) slot.textContent = text;
      slot.parentElement!.hidden = !text && slot.assignedNodes().length === 0;
    }
  }

  #renderLogos() {
    const list = this.shadowRoot!.querySelector('.logos')!;
    list.replaceChildren(
      ...this.#logos.map((logo) => {
        const img = document.createElement('img');
        img.className = 'logo';
        img.src = logo.src;
        img.alt = logo.alt;

        const item = document.createElement('li');
        if (logo.href) {
          const link = document.createElement('a');
          link.href = logo.href;
          link.target = '_blank';
          link.rel = 'noopener noreferrer';
          link.append(img);
          item.append(link);
        } else {
          item.append(img);
        }
        return item;
      }),
    );
    (list as HTMLElement).hidden = this.#logos.length === 0;
  }
}

if (typeof customElements !== 'undefined' && !customElements.get('mc-footer')) {
  customElements.define('mc-footer', McFooter);
}

declare global {
  interface HTMLElementTagNameMap {
    'mc-footer': McFooter;
  }
}
