import { html, LitElement, nothing, unsafeCSS, type PropertyValues } from 'lit';
import carbonStyles from '../../styles/generated/carbon-header.styles';
import logoUrl from '../../assets/metacentrum-logo.svg';
import { headerStyles, slottedStyles } from './header.styles';
import { chevronDownIcon, closeIcon, launchIcon, logoutIcon, menuIcon, userIcon } from './icons';

export interface McHeaderNavItem {
  label: string;
  href?: string;
  active?: boolean;
  /** Opens in a new tab and shows an external-link icon. */
  external?: boolean;
  /** Turns the item into a dropdown. */
  children?: McHeaderNavItem[];
}

export interface McHeaderUser {
  firstName: string;
  lastName: string;
  avatarUrl?: string;
  /** Makes the name a link, e.g. to a profile (opens in a new tab). */
  href?: string;
}

export interface McHeaderLanguage {
  label: string;
  /** Accessible name */
  ariaLabel?: string;
}

export interface McHeaderAction {
  label: string;
  active?: boolean;
}

export interface McHeaderNavigateDetail {
  href: string;
  /** "nav-0", "nav-2-1", … */
  key: string;
}

const MOBILE_QUERY = '(max-width: 65.98rem)';
const SKIP_LABEL = 'Přeskočit na obsah';
const SKIP_HREF = '#main-content';

let slottedSheetAdded = false;
function addSlottedSheet() {
  if (slottedSheetAdded) return;
  slottedSheetAdded = true;
  const sheet = new CSSStyleSheet();
  sheet.replaceSync(slottedStyles);
  document.adoptedStyleSheets = [...document.adoptedStyleSheets, sheet];
}

/**
 * Fixed left sidebar on wide screens; on small screens a top bar with a menu button.
 * Attributes, slots and events: see README.
 */
export class McHeader extends LitElement {
  static styles = [unsafeCSS(carbonStyles), unsafeCSS(headerStyles)];

  static properties = {
    appTitle: { attribute: 'app-title' },
    navItems: { attribute: 'nav-items', type: Array },
    actions: { type: Array },
    user: { type: Object },
    logout: { type: Boolean },
    logoutLabel: { attribute: 'logout-label' },
    language: { type: Object },
    openMenuLabel: { attribute: 'open-menu-label' },
    closeMenuLabel: { attribute: 'close-menu-label' },
    menuOpen: { type: Boolean, attribute: 'menu-open', reflect: true },
    _isMobile: { state: true },
    _panelGroups: { state: true },
    _slots: { state: true },
  };

  declare appTitle: string;
  declare navItems: McHeaderNavItem[];
  declare actions: McHeaderAction[];
  declare user: McHeaderUser | undefined;
  declare logout: boolean;
  declare logoutLabel: string;
  declare language: McHeaderLanguage | undefined;
  declare openMenuLabel: string;
  declare closeMenuLabel: string;
  /** Reflected so page CSS can style slotted icons in the mobile menu. */
  declare menuOpen: boolean;

  declare private _isMobile: boolean;
  declare private _panelGroups: Set<number>;
  declare private _slots: Set<string>;

  #slotObserver = new MutationObserver(() => this.#readSlots());
  #mobile?: MediaQueryList;
  #activeKey = '';

  constructor() {
    super();
    this.appTitle = 'MetaCentrum';
    this.navItems = [];
    this.actions = [];
    this.logout = false;
    this.logoutLabel = 'Odhlásit se';
    this.openMenuLabel = 'Otevřít menu';
    this.closeMenuLabel = 'Zavřít menu';
    this.menuOpen = false;
    this._isMobile = false;
    this._panelGroups = new Set();
    this._slots = new Set();
  }

  connectedCallback() {
    super.connectedCallback();
    addSlottedSheet();
    this.#readSlots();
    this.#slotObserver.observe(this, { childList: true, subtree: true, attributeFilter: ['slot'] });
    this.#mobile = window.matchMedia(MOBILE_QUERY);
    this.#mobile.addEventListener('change', this.#onBreakpoint);
    this._isMobile = this.#mobile.matches;
    document.addEventListener('keydown', this.#onDocumentKeyDown);
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    this.#slotObserver.disconnect();
    this.#mobile?.removeEventListener('change', this.#onBreakpoint);
    document.removeEventListener('keydown', this.#onDocumentKeyDown);
  }

  protected willUpdate(changed: PropertyValues<this>) {
    // navItems is a new array on every React render, so react to the current page only
    const activeKey = this.navItems.map((item) => Boolean(item.active || item.children?.some((c) => c.active))).join();
    const pageChanged = activeKey !== this.#activeKey;
    this.#activeKey = activeKey;

    // Groups holding the current page start open
    if ((changed.has('menuOpen') && this.menuOpen) || (this.#sidebar && pageChanged)) {
      this._panelGroups = new Set(
        this.navItems.flatMap((item, i) => (item.children?.some((c) => c.active) ? [i] : [])),
      );
    }
  }

  #readSlots() {
    const names = new Set(Array.from(this.children, (child) => child.slot).filter(Boolean));
    const same = names.size === this._slots.size && [...names].every((n) => this._slots.has(n));
    if (!same) this._slots = names;
  }

  #emit(type: string, detail?: unknown) {
    return this.dispatchEvent(new CustomEvent(type, { detail, bubbles: true, composed: true, cancelable: true }));
  }

  #onInternalLink(event: MouseEvent, href: string | undefined, key: string) {
    if (event.defaultPrevented || event.button !== 0 || href === undefined) return;
    if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
    const detail: McHeaderNavigateDetail = { href, key };
    if (!this.#emit('mc-navigate', detail)) event.preventDefault();
  }

  #onBreakpoint = () => {
    this._isMobile = Boolean(this.#mobile?.matches);
    if (!this._isMobile) this.menuOpen = false;
  };

  /** Wide screens get the sidebar, small ones the top bar */
  get #sidebar() {
    return !this._isMobile;
  }

  #onDocumentKeyDown = (event: KeyboardEvent) => {
    if (event.key !== 'Escape') return;
    if (this.menuOpen) {
      this.menuOpen = false;
      this.renderRoot.querySelector<HTMLElement>('.mc-header__menu-toggle')?.focus();
    }
  };

  #navIcon(name: string) {
    return this._slots.has(name) ? html`<span class="mc-header__nav-icon"><slot name=${name}></slot></span>` : nothing;
  }

  #externalProps(item: McHeaderNavItem) {
    return item.external ? { target: '_blank', rel: 'noopener noreferrer' } : { target: undefined, rel: undefined };
  }

  #user(user: McHeaderUser) {
    const content = html`<span class="mc-header__avatar" aria-hidden="true"
        >${user.avatarUrl ? html`<img src=${user.avatarUrl} alt="" />` : userIcon}</span
      ><span class="mc-header__user-name">${user.firstName} ${user.lastName}</span>${user.href ? launchIcon : nothing}`;
    return user.href
      ? html`<a class="mc-header__user" href=${user.href} target="_blank" rel="noopener noreferrer">${content}</a>`
      : html`<div class="mc-header__user">${content}</div>`;
  }

  #onAction(index: number) {
    this.#emit('mc-action', { index });
  }

  #panel() {
    return html`<div
      id="menu"
      class="mc-header__panel"
      @click=${(e: MouseEvent) => (e.target as HTMLElement).closest('a') && (this.menuOpen = false)}
    >
      ${this.#panelContent()}
    </div>`;
  }

  #sidebarRender() {
    const { appTitle } = this;
    return html`<aside aria-label=${appTitle} class="mc-sidebar" part="header">
      <a class="cds--skip-to-content" href=${SKIP_HREF} tabindex="0">${SKIP_LABEL}</a>
      <div class="mc-sidebar__name"><slot name="logo"><img class="mc-header__logo" alt="" src=${logoUrl} /></slot></div>
      ${this.#panelContent()}
    </aside>`;
  }

  #panelContent() {
    const { navItems, actions, user, language } = this;
    const hasFooter = (actions.length > 0 || user || language);
    const run = (fn: () => void) => () => {
      fn();
      this.menuOpen = false;
    };
    const panelLink = (item: McHeaderNavItem, key: string) => {
      const { target, rel } = this.#externalProps(item);
      return html`<a
        href=${item.href ?? nothing}
        target=${target ?? nothing}
        rel=${rel ?? nothing}
        class="mc-header__panel-link"
        aria-current=${item.active ? 'page' : nothing}
        data-key=${`panel-${key}`}
        @click=${(e: MouseEvent) => !item.external && this.#onInternalLink(e, item.href, key)}
        >${this.#navIcon(`nav-icon-${key.slice(4)}`)}${item.label}${item.external ? launchIcon : nothing}</a
      >`;
    };
    const panelGroup = (item: McHeaderNavItem, index: number) => {
      const open = this._panelGroups.has(index);
      const current = item.active || item.children!.some((c) => c.active);
      const toggle = () => {
        const groups = new Set(this._panelGroups);
        if (open) groups.delete(index);
        else groups.add(index);
        this._panelGroups = groups;
      };
      return html`<button
          type="button"
          class="mc-header__panel-link mc-header__panel-group"
          aria-expanded=${open ? 'true' : 'false'}
          data-current=${current ? 'true' : nothing}
          data-key=${`panel-group-${index}`}
          @click=${toggle}
        >
          ${this.#navIcon(`nav-icon-${index}`)}${item.label}${chevronDownIcon('mc-header__panel-chevron')}
        </button>
        ${open
          ? html`<ul class="mc-header__panel-sublist">
              ${item.children!.map((child, j) => html`<li>${panelLink(child, `nav-${index}-${j}`)}</li>`)}
            </ul>`
          : nothing}`;
    };

    return html`${navItems.length > 0
        ? html`<nav aria-label="Menu" class="mc-header__panel-nav">
            <ul class="mc-header__panel-list">
              ${navItems.map(
                (item, i) => html`<li>${item.children ? panelGroup(item, i) : panelLink(item, `nav-${i}`)}</li>`,
              )}
            </ul>
          </nav>`
        : nothing}
      ${hasFooter
        ? html`<div class="mc-header__panel-footer">
            ${user
              ? html`<div class="mc-header__panel-group-section">
                  ${this.#user(user)}
                  ${this.logout
                    ? html`<button type="button" class="mc-header__panel-action" @click=${run(() => this.#emit('mc-logout'))}>
                        ${logoutIcon}${this.logoutLabel}
                      </button>`
                    : nothing}
                </div>`
              : nothing}
            ${actions.length > 0
              ? html`<div class="mc-header__panel-group-section">
                  ${actions.map(
                    (action, i) => html`<button
                      type="button"
                      class="mc-header__panel-action"
                      aria-pressed=${action.active === undefined ? nothing : String(action.active)}
                      data-key=${`panel-action-${i}`}
                      @click=${run(() => this.#onAction(i))}
                    >
                      <slot name=${`action-icon-${i}`}></slot>${action.label}
                    </button>`,
                  )}
                </div>`
              : nothing}
            ${language
              ? html`<div class="mc-header__panel-group-section">
                  <button
                    type="button"
                    class="mc-header__panel-action"
                    aria-label=${language.ariaLabel ?? language.label}
                    @click=${run(() => this.#emit('mc-language'))}
                  >
                    <span class="mc-header__panel-language">${language.label}</span>${language.ariaLabel}
                  </button>
                </div>`
              : nothing}
          </div>`
        : nothing}`;
  }

  render() {
    if (this.#sidebar) return this.#sidebarRender();
    const { appTitle, navItems, actions, user, language } = this;
    const hasMenu = navItems.length > 0 || actions.length > 0 || Boolean(user) || Boolean(language);
    const menuLabel = this.menuOpen ? this.closeMenuLabel : this.openMenuLabel;

    return html`<header aria-label=${appTitle} class="cds--header mc-header" part="header">
      <a class="cds--skip-to-content" href=${SKIP_HREF} tabindex="0">${SKIP_LABEL}</a>
      <div class="cds--header__name"><slot name="logo"><img class="mc-header__logo" alt="" src=${logoUrl} /></slot></div>
      ${hasMenu
        ? html`<button
              aria-expanded=${this.menuOpen ? 'true' : 'false'}
              aria-controls="menu"
              aria-label=${menuLabel}
              class="mc-header__menu-toggle cds--header__action cds--header__menu-trigger ${this.menuOpen ? 'cds--header__action--active' : ''} cds--header__menu-toggle"
              title=${menuLabel}
              type="button"
              @click=${() => (this.menuOpen = !this.menuOpen)}
            >
              ${this.menuOpen ? closeIcon : menuIcon}
            </button>
            ${this.menuOpen ? this.#panel() : nothing}`
        : nothing}
    </header>`;
  }
}

if (typeof customElements !== 'undefined' && !customElements.get('mc-header')) {
  customElements.define('mc-header', McHeader);
}

declare global {
  interface HTMLElementTagNameMap {
    'mc-header': McHeader;
  }
}
